/**
 * Job message contracts (queue + worker boundary).
 *
 * One versioned envelope for every job type. TypeScript services (BullMQ
 * producers) and Python workers (consumers) validate against these schemas:
 * the JSON Schema artifacts generated by `pnpm gen` are the single source.
 *
 * Queue naming: `lathe.<job.type>` (dots preserved), e.g. `lathe.analysis.transcribe`.
 */

import { z } from "zod";
import type { UploadId } from "./ids.js";
import { ProjectId, JobId, AssetId } from "./ids.js";
import { JobPriority, JobState, Summary, Timestamp } from "./common.js";
import type { Operation } from "./operations.js";

export const JOB_CONTRACT_VERSION = "1.0.0";

export const JobType = z.enum([
  "proxy.generate",
  "analysis.transcribe",
  "analysis.diarize",
  "analysis.shots",
  "analysis.audio_features",
  "analysis.embeddings",
  "analysis.visual",
  "preview.render",
  "render.full",
  "export.interchange",
  "export.captions",
  "verify.run",
]);
export type JobType = z.infer<typeof JobType>;

/** Queues are derived from job type; Python and TS must agree. */
export function queueName(type: JobType): string {
  return `lathe.${type}`;
}

// ---------------------------------------------------------------------------
// Payloads (one per job type)
// ---------------------------------------------------------------------------

const basePayload = z.object({
  project_id: ProjectId,
  asset_id: AssetId.optional(),
});

export const JobPayloads = {
  "proxy.generate": basePayload.extend({
    /** Proxy ladder: 720p intra proxy for preview work. */
    resolutions: z.array(z.enum(["540p", "720p", "1080p"])).default(["720p"]),
    all_intra: z.boolean().default(true),
  }),

  "analysis.transcribe": basePayload.extend({
    language: z.string().regex(/^[a-z]{2}(-[A-Z]{2})?$/).optional(),
    /** Model identifier behind the ASR interface (faster-whisper default). */
    engine: z.string().default("faster-whisper"),
    word_timestamps: z.boolean().default(true),
  }),

  "analysis.diarize": basePayload.extend({
    /** Fallback: label everything spk_1 when no diarizer is installed. */
    allow_single_speaker_fallback: z.boolean().default(true),
    min_speakers: z.number().int().min(1).default(1),
    max_speakers: z.number().int().min(1).max(16).default(8),
  }),

  "analysis.shots": basePayload.extend({
    /** SceneDetect content detector threshold. */
    threshold: z.number().min(5).max(80).default(27),
    min_scene_len_s: z.number().min(0).max(60).default(0.8),
  }),

  "analysis.audio_features": basePayload.extend({
    silence_threshold_db: z.number().min(-80).max(-10).default(-35),
    min_silence_s: z.number().min(0.05).max(5).default(0.3),
    loudness_window_s: z.number().min(0.1).max(10).default(3),
    detect_beats: z.boolean().default(true),
  }),

  "analysis.embeddings": basePayload.extend({
    /** Which content to embed: transcript segments, shot keyframes, or both. */
    targets: z.array(z.enum(["segments", "shots"])).default(["segments"]),
    engine: z.string().default("local-minilm"),
  }),

  "analysis.visual": basePayload.extend({
    detect_faces: z.boolean().default(true),
    detect_ocr: z.boolean().default(true),
    detect_activity: z.boolean().default(true),
    describe_shots: z.boolean().default(true),
  }),

  "preview.render": basePayload.extend({
    /** Timeline version this preview renders. */
    timeline_version: z.number().int().nonnegative(),
    range: z
      .object({ start_s: z.number().nonnegative(), end_s: z.number().nonnegative() })
      .optional(),
    /** Proxy-based: never touches the full-quality pipeline. */
    quality: z.enum(["proxy"]).default("proxy"),
  }),

  "render.full": basePayload.extend({
    timeline_version: z.number().int().nonnegative(),
    preset_id: z.string().min(1).max(64),
    /** When true the planner may stream-copy unchanged segments (smart render). */
    smart_render: z.boolean().default(true),
    /** Parallel chunk plan (M4); empty = let the planner decide. */
    chunks: z.array(z.object({ index: z.number().int().nonnegative(), start_s: z.number().nonnegative(), end_s: z.number().nonnegative() })).default([]),
    /** Render cache hint: content hash of (timeline, asset hashes, preset). */
    content_hash: z.string().min(8).max(128).optional(),
  }),

  "export.interchange": basePayload.extend({
    timeline_version: z.number().int().nonnegative(),
    format: z.enum(["otio", "fcpxml", "edl"]),
  }),

  "export.captions": basePayload.extend({
    timeline_version: z.number().int().nonnegative(),
    format: z.enum(["srt", "vtt"]),
    burn_in: z.boolean().default(false).describe("Burn into video (render) vs sidecar file"),
  }),

  "verify.run": basePayload.extend({
    timeline_version: z.number().int().nonnegative(),
    render_job_id: z.string().regex(/^job_[A-Za-z0-9]{10,64}$/).optional(),
    style_id: z.string().max(64).optional(),
  }),
} satisfies Record<JobType, z.ZodTypeAny>;

// ---------------------------------------------------------------------------
// Envelope: <-> workers
// ---------------------------------------------------------------------------

export const JobEnvelope = z.object({
  job_id: JobId,
  contract_version: z.literal(JOB_CONTRACT_VERSION),
  type: JobType,
  project_id: ProjectId,
  payload: z.record(z.string(), z.unknown()).describe("Validated against the per-type payload schema"),
  /** Idempotency: retries of the same logical work carry the same key. */
  idempotency_key: z.string().min(8).max(128),
  attempt: z.number().int().min(0).default(0),
  max_attempts: z.number().int().min(1).default(3),
  priority: JobPriority.default(2),
  created_at: Timestamp,
  /** Opaque context for retries/debugging; never contains secrets. */
  trace: z.record(z.string(), z.string()).optional(),
});
export type JobEnvelope = z.infer<typeof JobEnvelope>;

export const JobProgress = z.object({
  job_id: JobId,
  state: JobState,
  /** 0..1 */
  progress: z.number().min(0).max(1).default(0),
  stage: z.string().max(64).optional(),
  message: z.string().max(200).optional(),
});
export type JobProgress = z.infer<typeof JobProgress>;

export const JobError = z.object({
  code: z.string().min(1).max(64),
  message: z.string().min(1).max(500),
  retryable: z.boolean(),
  suggested_fix: z.string().min(1).max(500).optional(),
  details: z.record(z.string(), z.unknown()).optional(),
});
export type JobError = z.infer<typeof JobError>;

/** Worker -> broker completion message. */
export const JobResultMessage = z.object({
  job_id: JobId,
  contract_version: z.literal(JOB_CONTRACT_VERSION),
  state: z.enum(["completed", "failed"]),
  result: z.record(z.string(), z.unknown()).optional(),
  error: JobError.optional(),
  metrics: z
    .object({
      wall_s: z.number().nonnegative().finite(),
      cpu_s: z.number().nonnegative().finite().optional(),
      gpu_s: z.number().nonnegative().finite().optional(),
    })
    .optional(),
});
export type JobResultMessage = z.infer<typeof JobResultMessage>;

// ---------------------------------------------------------------------------
// Analysis result payloads (what the API persists from each worker)
// ---------------------------------------------------------------------------

export const TranscriptResult = z.object({
  language: z.string(),
  duration_s: z.number().nonnegative().finite(),
  words: z.array(
    z.object({
      w: z.string(),
      s: z.number().nonnegative().finite(),
      e: z.number().nonnegative().finite(),
      c: z.number().min(0).max(1),
      speaker_hint: z.string().optional(),
    }),
  ),
  engine: z.string(),
  model: z.string().optional(),
});
export type TranscriptResult = z.infer<typeof TranscriptResult>;

export const DiarizationResult = z.object({
  speakers: z.array(
    z.object({
      id: z.string().regex(/^spk_[A-Za-z0-9]{10,64}$/),
      total_speech_s: z.number().nonnegative().finite(),
      fallback: z.boolean().describe("true when labeled by the single-speaker fallback"),
    }),
  ),
  turns: z.array(
    z.object({
      speaker: z.string().regex(/^spk_[A-Za-z0-9]{10,64}$/),
      start_s: z.number().nonnegative().finite(),
      end_s: z.number().nonnegative().finite(),
    }),
  ),
});
export type DiarizationResult = z.infer<typeof DiarizationResult>;

export const ShotsResult = z.object({
  shots: z.array(
    z.object({
      id: z.string().regex(/^sht_[A-Za-z0-9]{10,64}$/),
      start_s: z.number().nonnegative().finite(),
      end_s: z.number().nonnegative().finite(),
      score: z.number().finite().optional().describe("Detector strength"),
    }),
  ),
  detector: z.string(),
});
export type ShotsResult = z.infer<typeof ShotsResult>;

export const AudioFeaturesResult = z.object({
  silences: z.array(z.object({ s: z.number().nonnegative().finite(), e: z.number().nonnegative().finite() })),
  loudness_curve: z.array(
    z.object({ t: z.number().nonnegative().finite(), lufs: z.number().finite() }),
  ),
  music_ranges: z.array(
    z.object({
      s: z.number().nonnegative().finite(),
      e: z.number().nonnegative().finite(),
      kind: z.enum(["music", "speech", "mixed", "silence"]),
    }),
  ),
  beats: z.array(z.object({ t: z.number().nonnegative().finite(), strength: z.number().min(0).max(1) })).optional(),
});
export type AudioFeaturesResult = z.infer<typeof AudioFeaturesResult>;

/** Public status view of a job (get_status). */
export const JobStatus = z.object({
  job_id: JobId,
  type: JobType,
  state: JobState,
  progress: z.number().min(0).max(1),
  stage: z.string().optional(),
  created_at: Timestamp,
  updated_at: Timestamp.optional(),
  error: JobError.optional(),
});
export type JobStatus = z.infer<typeof JobStatus>;

export const GetStatusResponse = z.object({
  project_id: ProjectId,
  jobs: z.array(JobStatus),
  /** Brief readiness mirror so one call answers "can I edit yet?". */
  readiness: z.record(z.string(), z.unknown()).optional(),
  summary: Summary,
});
export type GetStatusResponse = z.infer<typeof GetStatusResponse>;

/** Re-export for tools that reference payloads. */
export type { UploadId };
export type { Operation };